<script setup>
import { computed,onMounted,ref } from 'vue';import DashboardLayout from '../../layouts/DashboardLayout.vue';import MemberSelect from '../../components/MemberSelect.vue';import { getMembers } from '../../services/member.service.js';import { configureShares,getShares,purchaseShares } from '../../services/share.service.js';import { useAuthStore } from '../../stores/auth.store.js';
const auth=useAuthStore();const cycle=ref(null);const settings=ref(null);const purchases=ref([]);const holdings=ref([]);const members=ref([]);const summary=ref({shares:0,value:0,members:0});const loading=ref(false);const saving=ref(false);const errorMessage=ref('');const successMessage=ref('');const showSettings=ref(false);const showPurchase=ref(false);const search=ref('');const config=ref({share_price:'',minimum_shares:0,maximum_shares:''});const form=ref({member_id:'',number_of_shares:'',reference:'',notes:''});
const canManage=computed(()=>['admin','chairperson','treasurer'].includes(auth.user?.role));const canPurchase=computed(()=>['admin','treasurer'].includes(auth.user?.role));const filtered=computed(()=>holdings.value.filter(item=>`${item.first_name} ${item.last_name} ${item.phone}`.toLowerCase().includes(search.value.toLowerCase())));const selectedHolding=computed(()=>holdings.value.find(item=>Number(item.member_id)===Number(form.value.member_id)));const purchaseValue=computed(()=>Number(form.value.number_of_shares||0)*Number(settings.value?.share_price||0));const currency=value=>new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(value||0);const date=value=>new Date(value).toLocaleDateString();
const load=async()=>{loading.value=true;errorMessage.value='';try{const [sharesResponse,membersResponse]=await Promise.all([getShares(),getMembers()]);const data=sharesResponse.data?.data||{};cycle.value=data.cycle;settings.value=data.settings;purchases.value=data.purchases||[];holdings.value=data.members||[];summary.value=data.summary||summary.value;members.value=membersResponse.data?.data||[];if(settings.value)config.value={share_price:settings.value.share_price,minimum_shares:settings.value.minimum_shares,maximum_shares:settings.value.maximum_shares||''};}catch(error){errorMessage.value=error.response?.data?.message||'Unable to load shares.';}finally{loading.value=false;}};
const saveSettings=async()=>{saving.value=true;errorMessage.value='';try{await configureShares({...config.value,share_price:Number(config.value.share_price),minimum_shares:Number(config.value.minimum_shares),maximum_shares:config.value.maximum_shares?Number(config.value.maximum_shares):null});showSettings.value=false;successMessage.value='Cycle share rules saved.';await load();}catch(error){errorMessage.value=error.response?.data?.message||'Unable to save share rules.';}finally{saving.value=false;}};
const buy=async()=>{saving.value=true;errorMessage.value='';try{await purchaseShares({...form.value,member_id:Number(form.value.member_id),number_of_shares:Number(form.value.number_of_shares),reference:form.value.reference||null,notes:form.value.notes||null});showPurchase.value=false;form.value={member_id:'',number_of_shares:'',reference:'',notes:''};successMessage.value='Hisa purchase recorded.';await load();}catch(error){errorMessage.value=error.response?.data?.message||'Unable to record share purchase.';}finally{saving.value=false;}};onMounted(load);
</script>
<template><DashboardLayout page-title="Shares / Hisa" page-subtitle="Member share capital">
<section class="page-header"><div class="page-header-copy"><p class="page-header-label">{{ cycle?.name||'No active cycle' }}</p><h2>Shares / Hisa</h2><p class="page-header-text mb-0">Track member share capital separately from ordinary savings with a fixed cycle price and purchase limits.</p></div><div class="header-actions"><button v-if="canManage&&cycle?.status==='active'" class="btn btn-outline-primary" @click="showSettings=true"><i class="bi bi-sliders me-2"></i>Share rules</button><button v-if="canPurchase&&settings&&cycle?.status==='active'" class="btn btn-primary" @click="showPurchase=true"><i class="bi bi-plus-lg me-2"></i>Buy shares</button></div></section>
<div v-if="errorMessage&&!showSettings&&!showPurchase" class="alert alert-warning">{{ errorMessage }}</div><div v-if="successMessage" class="alert alert-success">{{ successMessage }}</div><div v-if="cycle&&!settings&&!loading" class="setup-notice"><i class="bi bi-info-circle"></i><span><strong>Configure Hisa for this cycle</strong>Set the share price and optional member limits before recording purchases.</span></div>
<section class="stats"><article><small>Share price</small><strong>{{ settings?currency(settings.share_price):'Not configured' }}</strong></article><article><small>Shares purchased</small><strong>{{ summary.shares }}</strong></article><article><small>Total share value</small><strong class="value">{{ currency(summary.value) }}</strong></article><article><small>Members holding shares</small><strong>{{ summary.members }}</strong></article></section>
<section v-if="settings" class="rules"><span><small>Minimum per member</small><strong>{{ settings.minimum_shares }} shares</strong></span><span><small>Maximum per member</small><strong>{{ settings.maximum_shares?`${settings.maximum_shares} shares`:'No maximum' }}</strong></span><span><small>Price locked after first purchase</small><strong>{{ purchases.length?'Yes':'Not yet' }}</strong></span></section>
<section class="card panel-card"><div class="card-body"><div class="panel-head"><div><h5 class="mb-1">Member holdings</h5><p class="text-muted mb-0">Cycle share counts and their recorded monetary value.</p></div><label><i class="bi bi-search"></i><input v-model="search" placeholder="Search member" /></label></div><div class="holdings"><div v-if="loading" class="empty">Loading shares...</div><article v-for="item in filtered" v-else :key="item.member_id"><div class="member"><span>{{ item.first_name[0] }}{{ item.last_name[0] }}</span><div><strong>{{ item.first_name }} {{ item.last_name }}</strong><small>{{ item.phone }}</small></div></div><div><small>Shares</small><strong>{{ item.shares }}</strong></div><div><small>Share value</small><strong class="value">{{ currency(item.value) }}</strong></div><div v-if="settings?.maximum_shares" class="limit"><small>{{ item.shares }} / {{ settings.maximum_shares }}</small><span><i :style="{width:`${Math.min(100,item.shares/settings.maximum_shares*100)}%`}"></i></span></div></article></div></div></section>
<section class="card panel-card mt-3"><div class="card-body"><h5>Purchase history</h5><div class="table-responsive"><table class="table align-middle history"><thead><tr><th>Date</th><th>Member</th><th>Shares</th><th>Price</th><th>Total value</th><th>Reference</th><th>Recorded by</th></tr></thead><tbody><tr v-if="!purchases.length"><td colspan="7" class="text-center py-4">No share purchases recorded.</td></tr><tr v-for="item in purchases" :key="item.id"><td>{{ date(item.purchased_at) }}</td><td><strong>{{ item.first_name }} {{ item.last_name }}</strong></td><td>{{ item.number_of_shares }}</td><td>{{ currency(item.share_price) }}</td><td><strong>{{ currency(item.total_value) }}</strong></td><td><code>{{ item.reference||`HISA-${item.id}` }}</code></td><td>{{ item.recorded_by_name||'System' }}</td></tr></tbody></table></div></div></section>
<div v-if="showSettings" class="modal-backdrop"><div class="modal-panel"><div class="modal-panel-header"><div><p class="page-header-label mb-2">{{ cycle?.name }}</p><h5>Share rules</h5></div><button class="btn btn-close" @click="showSettings=false"></button></div><form @submit.prevent="saveSettings"><div class="row g-3"><div class="col-12"><label class="form-label">Price per share (TZS)</label><input v-model="config.share_price" class="form-control" type="number" min="1" required :disabled="purchases.length>0" /></div><div class="col-6"><label class="form-label">Minimum shares</label><input v-model="config.minimum_shares" class="form-control" type="number" min="0" required /></div><div class="col-6"><label class="form-label">Maximum shares</label><input v-model="config.maximum_shares" class="form-control" type="number" min="1" placeholder="No limit" /></div></div><p v-if="purchases.length" class="lock-note"><i class="bi bi-lock"></i>Share price is locked because purchases exist.</p><p v-if="errorMessage" class="text-danger small mt-3">{{ errorMessage }}</p><div class="modal-actions"><button type="button" class="btn btn-outline-secondary" @click="showSettings=false">Cancel</button><button class="btn btn-primary" :disabled="saving">{{ saving?'Saving...':'Save rules' }}</button></div></form></div></div>
<div v-if="showPurchase" class="modal-backdrop"><div class="modal-panel"><div class="modal-panel-header"><div><p class="page-header-label mb-2">New Hisa purchase</p><h5>Buy member shares</h5></div><button class="btn btn-close" @click="showPurchase=false"></button></div><form @submit.prevent="buy"><div class="row g-3"><div class="col-12"><label class="form-label">Member</label><MemberSelect v-model="form.member_id" :members="members" required /></div><div class="col-12 col-md-6"><label class="form-label">Number of shares</label><input v-model="form.number_of_shares" class="form-control" type="number" min="1" step="1" required /></div><div class="col-12 col-md-6"><label class="form-label">Reference</label><input v-model="form.reference" class="form-control" /></div><div class="col-12"><label class="form-label">Notes</label><textarea v-model="form.notes" class="form-control" rows="2"></textarea></div></div><div class="purchase-summary"><span>Current holding <strong>{{ selectedHolding?.shares||0 }} shares</strong></span><span>Purchase value <strong>{{ currency(purchaseValue) }}</strong></span></div><p v-if="errorMessage" class="text-danger small mt-3">{{ errorMessage }}</p><div class="modal-actions"><button type="button" class="btn btn-outline-secondary" @click="showPurchase=false">Cancel</button><button class="btn btn-primary" :disabled="saving">{{ saving?'Recording...':'Record purchase' }}</button></div></form></div></div>
</DashboardLayout></template>
<style scoped>
.header-actions{display:flex;gap:.5rem}.setup-notice{display:flex;gap:.6rem;margin-bottom:1rem;padding:.8rem;border-radius:9px;background:#f4f1ff;color:#7055dc}.setup-notice span,.setup-notice strong{display:block;font-size:.68rem}.stats{display:grid;grid-template-columns:repeat(2,1fr);gap:.7rem;margin-bottom:1rem}.stats article{padding:.9rem;border:1px solid #ebe9ef;border-radius:10px;background:#fff}.stats small,.stats strong{display:block}.stats small{color:#8c8792;font-size:.62rem}.stats strong{margin-top:.25rem}.value{color:#168657}.rules{display:flex;flex-wrap:wrap;gap:.6rem;margin-bottom:1rem}.rules span{padding:.55rem .7rem;border-radius:8px;background:#f6f4fb}.rules small,.rules strong{display:block}.rules small{color:#8c8792;font-size:.58rem}.rules strong{font-size:.68rem}.panel-head{display:flex;flex-direction:column;gap:.7rem;margin-bottom:1rem}.panel-head label{display:flex;align-items:center;gap:.4rem;padding:.45rem .6rem;border:1px solid #dedbe4;border-radius:8px}.panel-head input{border:0;outline:0;font-size:.68rem}.holdings{display:grid;gap:.55rem}.holdings article{display:grid;grid-template-columns:1fr auto auto;gap:.8rem;align-items:center;padding:.75rem;border:1px solid #ece9f0;border-radius:9px}.member{display:flex;align-items:center;gap:.55rem}.member>span{width:2rem;height:2rem;display:grid;place-items:center;border-radius:50%;background:#eeeaff;color:#7055dc;font-size:.62rem;font-weight:700}.member strong,.member small,.holdings article>div>small,.holdings article>div>strong{display:block}.member small,.holdings article>div>small{color:#908b95;font-size:.6rem}.limit{grid-column:1/-1}.limit>span{display:block;height:4px;border-radius:99px;background:#ece9f0}.limit i{display:block;height:100%;border-radius:inherit;background:#7055dc}.history{min-width:760px}.history code{color:#7055dc}.purchase-summary{display:flex;justify-content:space-between;margin-top:1rem;padding:.7rem;border-radius:8px;background:#f6f4fb;font-size:.65rem}.purchase-summary strong{display:block}.lock-note{display:flex;gap:.4rem;margin-top:.8rem;color:#a56a00;font-size:.65rem}@media(min-width:700px){.stats{grid-template-columns:repeat(4,1fr)}.panel-head{flex-direction:row;align-items:center;justify-content:space-between}.holdings article{grid-template-columns:minmax(200px,1fr) auto auto minmax(120px,.5fr)}.limit{grid-column:auto}}
</style>
